//	client.Posting.CreateBulk(builders...).
//		OnConflict(
//			// Update the row with the new values
//			// the was proposed for insertion.
//			sql.ResolveWithNewValues(),
//		).
//		// Override some of the fields with custom
//		// update values.
//		Update(func(u *ent.PostingUpsert) {
//			SetCreatedBy(v+v).
//		}).
//		Exec(ctx)
func (_c *PostingCreateBulk) OnConflict(opts ...sql.ConflictOption) *PostingUpsertBulk {
	_c.conflict = opts
	return &PostingUpsertBulk{
		create: _c,
	}
}

// OnConflictColumns calls `OnConflict` and configures the columns
// as conflict target. Using this option is equivalent to using:
//
//	client.Posting.Create().
//		OnConflict(sql.ConflictColumns(columns...)).
//		Exec(ctx)
func (_c *PostingCreateBulk) OnConflictColumns(columns ...string) *PostingUpsertBulk {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &PostingUpsertBulk{
		create: _c,
	}
}

// PostingUpsertBulk is the builder for "upsert"-ing
// a bulk of Posting nodes.
type PostingUpsertBulk struct {
	create *PostingCreateBulk
}

// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.Posting.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(posting.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *PostingUpsertBulk) UpdateNewValues() *PostingUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(posting.FieldID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(posting.FieldCreatedAt)
			}
			if _, exists := b.mutation.Amount(); exists {
				s.SetIgnore(posting.FieldAmount)
			}
			if _, exists := b.mutation.Side(); exists {
				s.SetIgnore(posting.FieldSide)
			}
			if _, exists := b.mutation.Memo(); exists {
				s.SetIgnore(posting.FieldMemo)
			}
		}
	}))
	return u
}

// Ignore sets each column to itself in case of conflict.
// Using this option is equivalent to using:
//
//	client.Posting.Create().
//		OnConflict(sql.ResolveWithIgnore()).
//		Exec(ctx)
func (u *PostingUpsertBulk) Ignore() *PostingUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithIgnore())
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
// Supported only by SQLite and PostgreSQL.
func (u *PostingUpsertBulk) DoNothing() *PostingUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.DoNothing())
	return u
}

// Update allows overriding fields `UPDATE` values. See the PostingCreateBulk.OnConflict
// documentation for more info.
func (u *PostingUpsertBulk) Update(set func(*PostingUpsert)) *PostingUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&PostingUpsert{UpdateSet: update})
	}))
	return u
}

// SetCreatedBy sets the "createdBy" field.
func (u *PostingUpsertBulk) SetCreatedBy(v uuid.UUID) *PostingUpsertBulk {
	return u.Update(func(s *PostingUpsert) {
		s.SetCreatedBy(v)
	})
}

// UpdateCreatedBy sets the "createdBy" field to the value that was provided on create.
func (u *PostingUpsertBulk) UpdateCreatedBy() *PostingUpsertBulk {
	return u.Update(func(s *PostingUpsert) {
		s.UpdateCreatedBy()
	})
}

// SetUpdatedBy sets the "updatedBy" field.
func (u *PostingUpsertBulk) SetUpdatedBy(v uuid.UUID) *PostingUpsertBulk {
	return u.Update(func(s *PostingUpsert) {
		s.SetUpdatedBy(v)
	})
}

// UpdateUpdatedBy sets the "updatedBy" field to the value that was provided on create.
func (u *PostingUpsertBulk) UpdateUpdatedBy() *PostingUpsertBulk {
	return u.Update(func(s *PostingUpsert) {
		s.UpdateUpdatedBy()
	})
}

// SetUpdatedAt sets the "updatedAt" field.
func (u *PostingUpsertBulk) SetUpdatedAt(v time.Time) *PostingUpsertBulk {
	return u.Update(func(s *PostingUpsert) {
		s.SetUpdatedAt(v)
	})
}

// UpdateUpdatedAt sets the "updatedAt" field to the value that was provided on create.
func (u *PostingUpsertBulk) UpdateUpdatedAt() *PostingUpsertBulk {
	return u.Update(func(s *PostingUpsert) {
		s.UpdateUpdatedAt()
	})
}

// Exec executes the query.
func (u *PostingUpsertBulk) Exec(ctx context.Context) error {
	if u.create.err != nil {
		return u.create.err
	}
	for i, b := range u.create.builders {
		if len(b.conflict) != 0 {
			return fmt.Errorf("ent: OnConflict was set for builder %d. Set it on the PostingCreateBulk instead", i)
		}
	}
	if len(u.create.conflict) == 0 {
		return errors.New("ent: missing options for PostingCreateBulk.OnConflict")
	}
	return u.create.Exec(ctx)
}

// ExecX is like Exec, but panics if an error occurs.
func (u *PostingUpsertBulk) ExecX(ctx context.Context) {
	if err := u.create.Exec(ctx); err != nil {
		panic(err)
	}
}
